<script setup lang="ts">
import { computed, ref } from 'vue'
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import { api } from '@/api/client'
const client=useQueryClient();const code=ref('');const file=ref<File>();const msg=ref('');const err=ref('');const logs=useQuery({queryKey:['activity-logs'],queryFn:async()=>{const r=await api.get('/activity-logs');return r.data.data?.data??r.data.data??[]}});const openapi=computed(()=>`${String(api.defaults.baseURL).replace(/\/$/,'')}/openapi.json`)
async function verify(){try{await api.post('/auth/email/verify',{code:code.value});msg.value='Email verified.'}catch(e:any){err.value=e.response?.data?.message??'Verification failed.'}}async function avatar(){if(!file.value){err.value='Choose an image first.';return}try{const data=new FormData();data.append('avatar',file.value);await api.post('/profile/avatar',data,{headers:{'Content-Type':'multipart/form-data'}});msg.value='Avatar uploaded.'}catch(e:any){err.value=e.response?.data?.message??'Avatar upload failed.'}}async function test(){try{await api.post('/notifications/test');msg.value='Test notification queued.';await client.invalidateQueries({queryKey:['notifications']})}catch(e:any){err.value=e.response?.data?.message??'Test notification could not be sent.'}}</script>
<template><header class="page-header"><div><p class="eyebrow">ADMINISTRATION</p><h1>Account &amp; developer tools</h1><p class="muted">Complete account verification, test delivery, and inspect system activity.</p></div></header><p v-if="msg" class="action-message success">{{msg}}</p><p v-if="err" class="action-message error">{{err}}</p><section class="settings-grid"><article class="panel membership-form"><h2>Verify email</h2><form @submit.prevent="verify"><label>Verification code<input v-model="code"/></label><button class="secondary-button">Confirm email</button></form></article><article class="panel membership-form"><h2>Avatar</h2><form @submit.prevent="avatar"><label>Image<input type="file" accept="image/*" @change="file=($event.target as HTMLInputElement).files?.[0]"/></label><button class="secondary-button">Upload avatar</button></form></article><article class="panel membership-form"><h2>Notification test</h2><p class="muted">Queue a test in-app notification for the current account.</p><button class="primary-button" @click="test">Send test notification</button></article><article class="panel"><h2>API documentation</h2><p class="muted">Open the live OpenAPI JSON used by integrations and API clients.</p><a class="secondary-button" :href="openapi" target="_blank" rel="noopener">Open OpenAPI JSON</a></article></section><section class="panel memberships-table"><h2>Activity logs</h2><div class="table-wrap"><table><thead><tr><th>Action</th><th>Actor</th><th>When</th></tr></thead><tbody><tr v-if="!logs.data.value?.length"><td colspan="3" class="table-empty">No activity records.</td></tr><tr v-for="log in logs.data.value" :key="log.id"><td>{{log.action||log.event||'Activity'}}</td><td>{{log.user_id?`User #${log.user_id}`:'System'}}</td><td>{{log.created_at}}</td></tr></tbody></table></div></section></template>
